export const allServices = serviceCategories.flatMap((cat) => cat.links);

export function categoryFor(slug) {
  return serviceCategories.find((c) => c.slug === slug);
}

export function serviceOf(slug) {
  return allServices.find((s) => s.slug === slug);
}

export function relatedServices(service, limit = 3) {
  return (service.related || [])
    .map((s) => serviceOf(s))
    .filter(Boolean)
    .slice(0, limit);
}

